import { expect, it } from 'vitest';
import { createSeededRandom } from '../random.js';

// Independent oracle from approved v0.3 plan, not generated by product code.
it.each([
  [0, [1144304738, 1416247, 958946056, 627933444, 2007157716]],
  [1, [2693262067, 11749833, 2265367787, 4213581821, 4159151403]],
  [42, [2581720956, 1925393290, 3661312704, 2876485805, 750819978]],
  [123, [3381219976, 766838775, 2127363934, 993692063, 1614012641]],
  [4294967295, [3850105811, 813802916, 3073704848, 4054706436, 3630262831]],
] as const)('matches independent uint32 words for seed %s', (seed, words) => {
  const random = createSeededRandom(seed);
  expect(words.map(() => Math.floor(random() * 2 ** 32))).toEqual(words);
});
